    "    Rata2_Harga=(\"Current_Price\", \"mean\"),\n",
    "    Rata2_Harga_Rekomendasi=(\"Recommended_Price_Tiered\", \"mean\"),\n",
    "    Rata2_Perubahan_Harga=(\"Price_Change_Tiered_%\", \"mean\"),\n",
    "    Margin_Lama=(\"Current_Margin\", \"mean\"),\n",
    "    Margin_Baru=(\"New_Margin_Tiered\", \"mean\"),\n",
    "    Rata2_Terjual=(\"sold_count\", \"mean\")\n",
    ").reset_index()\n",
    "\n",
    "display(tier_summary)\n",
    "\n",
    "# Analisis Top 5 SKU Perlu Kenaikan Harga Tertinggi\n",
    "top_gap = clean.sort_values(\"Margin_Gap\", ascending=False).head(5)\n",
    "cols_show = [\"product_id_clean\", \"product_name\", \"Current_Price\", \"Total_Cost\", \"Current_Margin\", \"Min_Margin\", \"Margin_Gap\"]\n",
    "print(\"\\n=== TOP 5 SKU DENGAN MARGIN GAP TERBESAR ===\")\n",
    "display(top_gap[cols_show])"
